fix(ai): truncate the realtime audio item that is playing on interruption (#25508)

## Background

in turn-based realtime sessions, when the user interrupts the model in
the middle of a response, AI SDK sends `conversation-item-truncate` so
the provider drops the audio the user never heard.

the event names an item and an `audioEndMs` offset within that item, but
AI SDK got both parts of that state wrong. this is because we queue
audio chunks back to back, and that queue wasn't accounted for:

- `currentResponseItemId` was overwritten by every `audio-delta`, so it
named the most recently *received* item, not the one currently playing
when it was interrupted
- `getPlaybackOffsetMs()` returned the time since playback last went
from idle to playing. that spans *every* queued item, not just the
currently item.

as a result, interrupting near the end of the answer was rejected by the
provider (`Audio content of 12950ms is already shorter than 13957ms`)

## Summary

- record each scheduled chunk's item, start and end time, and how much
of that item was scheduled before it
- new `getPlaybackPosition()` replaces `getPlaybackOffsetMs()`. It
returns `{ itemId, audioEndMs }` from the chunk currently playing
- `audioEndMs` is capped at the item's audio length (tracked in samples,
rounded down) so rounding can't overshoot the item

no public api changes

## End-to-End Verification

using OpenAI Realtime (`gpt-realtime`) over a real WebSocket with a
client-side function tool

<details>
<summary><code>/tmp/ai-sdk-25301/repro.mjs</code></summary>

```js
// Live repro for vercel/ai#25301.
// Real OpenAI Realtime WebSocket + real server VAD. Only the browser
// AudioContext is faked (Node has none), so we control the playback clock.
import 'dotenv/config';
import { openai } from '@ai-sdk/openai';
import {
  Experimental_AbstractRealtimeSession as Base,
  experimental_decodeRealtimeAudio as decode,
  experimental_getRealtimeToolDefinitions as getRealtimeToolDefinitions,
  generateSpeech,
  tool,
} from 'ai';
import { z } from 'zod';

const SCENARIO = process.env.SCENARIO ?? 'end-of-answer'; // or 'mid-answer' | 'preamble'
const sleep = ms => new Promise(r => setTimeout(r, ms));
const until = async (cond, ms = 60000) => {
  const t = Date.now();
  while (!cond()) {
    if (Date.now() - t > ms) throw new Error('timeout');
    await sleep(50);
  }
};

// --- fake AudioContext with a manual clock -------------------------------
let clock = 0;
globalThis.AudioContext = class {
  state = 'running';
  destination = {};
  constructor({ sampleRate }) {
    this.sampleRate = sampleRate;
  }
  get currentTime() {
    return clock;
  }
  async resume() {}
  async close() {}
  createBuffer(_c, length, rate) {
    return { duration: length / rate, getChannelData: () => new Float32Array(length) };
  }
  createBufferSource() {
    return { connect() {}, disconnect() {}, start() {}, stop() {} };
  }
};

// --- record what the SDK sends over the real socket -----------------------
const sent = [];
const RealWS = globalThis.WebSocket;
globalThis.WebSocket = class extends RealWS {
  send(data) {
    sent.push(JSON.parse(data));
    super.send(data);
  }
};

// --- token endpoint served in-process ------------------------------------
const tools = {
  getWeather: tool({
    description: 'Get the current weather for a city',
    inputSchema: z.object({ city: z.string() }),
  }),
};
const realFetch = globalThis.fetch;
globalThis.fetch = async (url, init) => {
  if (url !== '/token') return realFetch(url, init);
  const toolDefs = await getRealtimeToolDefinitions({ tools });
  const { sessionConfig } = JSON.parse(init.body);
  const t = await openai.experimental_realtime.getToken({
    model: 'gpt-realtime',
    sessionConfig: { ...sessionConfig, tools: toolDefs },
  });
  return Response.json({ ...t, tools: toolDefs });
};

class Session extends Base {
  setState() {}
  get snapshot() {
    return this.state;
  }
}

const itemDurations = new Map(); // itemId -> seconds of audio received
const errors = [];
let responsesDone = 0;
let sawToolCall = false;

const session = new Session({
  model: openai.experimental_realtime('gpt-realtime'),
  api: { token: '/token' },
  sessionConfig: {
    instructions:
      'Whenever you use a tool, FIRST say out loud "Let me check that for you." and THEN call the tool. ' +
      'After the tool result, answer in about three full sentences.',
  },
  onToolCall: async ({ toolCall }) => {
    sawToolCall = true;
    return { city: toolCall.args.city, temperature: 18, condition: 'cloudy' };
  },
  onEvent: e => {
    if (e.type === 'audio-delta') {
      const s = decode(e.delta).length / 24000;
      itemDurations.set(e.itemId, (itemDurations.get(e.itemId) ?? 0) + s);
    }
    if (e.type === 'response-done') responsesDone++;
  },
  onError: e => errors.push(e.message),
});

await session.connect({ capture: false });
await until(() => session.snapshot.status === 'connected');

// Clock stays frozen at 0 while audio streams in, i.e. the network delivers
// audio faster than it is played (normal), so items queue back-to-back.
session.sendTextMessage("What's the weather in Paris?");
await until(() => sawToolCall && responsesDone >= 2);

const items = [...itemDurations.entries()];
console.log('audio items in playback order:');
let start = 0;
for (const [id, d] of items) {
  console.log(`  ${id}  starts at ${start.toFixed(3)}s, length ${(d * 1000).toFixed(0)}ms`);
  start += d;
}
if (items.length < 2) throw new Error('model did not produce a spoken preamble; rerun');
const [[preId, preDur], [ansId, ansDur]] = items;

// Pick the moment the user interrupts (in playback time).
let expected;
if (SCENARIO === 'end-of-answer') {
  clock = preDur + ansDur - 0.5;
  expected = { itemId: ansId, audioEndMs: Math.round((ansDur - 0.5) * 1000) };
} else if (SCENARIO === 'mid-answer') {
  clock = preDur + 1;
  expected = { itemId: ansId, audioEndMs: 1000 };
} else {
  clock = preDur / 2;
  expected = { itemId: preId, audioEndMs: Math.round((preDur / 2) * 1000) };
}
console.log(`\nuser interrupts at playback time ${clock.toFixed(3)}s (${SCENARIO})`);

// Real barge-in: speak into the input buffer so server VAD fires speech_started.
const { audio } = await generateSpeech({
  model: openai.speech('gpt-4o-mini-tts'),
  text: 'Hey, wait, hold on a second.',
  outputFormat: 'pcm',
});
const pcm = audio.uint8Array;
for (let i = 0; i < pcm.length; i += 9600) {
  session.sendAudio(Buffer.from(pcm.subarray(i, i + 9600)).toString('base64'));
  await sleep(20);
}
await until(() => sent.some(e => e.type === 'conversation.item.truncate'), 15000);
await sleep(2000); // give the provider time to reject it

const t = sent.find(e => e.type === 'conversation.item.truncate');
console.log('\nSDK sent:   ', { itemId: t.item_id, audioEndMs: t.audio_end_ms });
console.log('expected:   ', expected);
console.log('errors:     ', errors);
session.dispose();
process.exit(0);
```

</details>

| user interrupts | before (main) | after (this branch) |
| --- | --- | --- |
| near the end of the answer | provider error: `Audio content of 9750ms
is already shorter than 12400ms` | correct item and offset |
| 1s into the answer | wrong offset (4250 ms instead of 1000 ms) |
correct item and offset |
| during the preamble | wrong item (truncated the answer instead of the
preamble) | correct item and offset |

