fix(mcp): align MCP Events with SEP-3415 (#25451)

## Background

`@ai-sdk/mcp` implements the earlier MCP Events draft and fails against
servers that follow the accepted
[SEP-3415](https://github.com/modelcontextprotocol/modelcontextprotocol/pull/3415):
it ignores `capabilities.extensions["io.modelcontextprotocol/events"]`,
omits `Mcp-Name` on `events/*` requests, and the webhook receiver
rejects deliveries whose `webhook-id` isn't the `eventId`.

## Summary

- Accept Events support from
`capabilities.extensions["io.modelcontextprotocol/events"]`, keeping the
legacy top-level `events` key as a fallback.
- Send `Mcp-Name` (from `params.name`) on `events/subscribe`,
`events/unsubscribe`, `events/poll` and `events/stream`. `events/list`
still sends none.
- Stop requiring `webhook-id` to equal `eventId` in
`createMCPEventWebhook`. The signature still covers `webhook-id`.

## Contributor Credit

@leggetter for the report and reproduction.

## End-to-End Verification

Ran the reproduction from the issue against the published package and
against this checkout's local build (`pnpm build` in `packages/mcp`,
then `node_modules/@ai-sdk/mcp` symlinked to `packages/mcp`).

<details>
<summary><code>repro.mjs</code></summary>

```js
// Minimal reproduction: @ai-sdk/mcp against an MCP server that follows SEP-3415
// (Events extension). No dependencies besides @ai-sdk/mcp. Run: node repro.mjs
import http from 'node:http';
import { createHmac, randomBytes } from 'node:crypto';
import {
  createMCPClient,
  experimental_createMCPEventWebhook as createMCPEventWebhook,
} from '@ai-sdk/mcp';

const EVENTS = 'io.modelcontextprotocol/events';

// A stateless Streamable HTTP server that records the Mcp-Name header it receives.
async function startServer(capabilities) {
  const received = [];
  const server = http.createServer(async (req, res) => {
    let body = '';
    for await (const chunk of req) body += chunk;
    const message = JSON.parse(body);
    if (message.id === undefined) return res.writeHead(202).end();
    received.push({ method: message.method, mcpName: req.headers['mcp-name'] ?? null });
    const results = {
      'server/discover': { supportedVersions: ['2026-07-28'], capabilities },
      'events/list': {
        events: [
          {
            name: 'incident.created',
            delivery: ['webhook'],
            inputSchema: { type: 'object' },
            payloadSchema: { type: 'object' },
          },
        ],
      },
      'events/subscribe': {
        id: 'sub_a3f1c8e2b0d49f7e',
        refreshBefore: new Date(Date.now() + 3_600_000).toISOString(),
        cursor: null,
        truncated: false,
      },
      'events/unsubscribe': {},
    };
    const result = results[message.method];
    res.writeHead(200, { 'content-type': 'application/json' }).end(
      JSON.stringify(
        result
          ? { jsonrpc: '2.0', id: message.id, result: { resultType: 'complete', ...result } }
          : { jsonrpc: '2.0', id: message.id, error: { code: -32601, message: 'Method not found' } },
      ),
    );
  });
  await new Promise(resolve => server.listen(0, '127.0.0.1', resolve));
  return { server, received, url: `http://127.0.0.1:${server.address().port}/mcp` };
}

function memoryStore() {
  const records = new Map();
  return {
    records,
    async get(key) { return records.get(key); },
    async getById(id) { return [...records.values()].find(r => r.id === id); },
    async set(s) { records.set(s.key, structuredClone(s)); },
    async update(key, patch) { records.set(key, { ...records.get(key), ...patch }); },
    async delete(key) { records.delete(key); },
  };
}

// 1. The server advertises Events the way SEP-3415 says: under capabilities.extensions.
{
  const { server, url } = await startServer({ extensions: { [EVENTS]: {} } });
  const client = await createMCPClient({
    transport: { type: 'http', url },
    experimental_events: { store: memoryStore() },
  });
  try {
    await client.experimental_events.list();
    console.log('1. events/list with extensions capability: OK');
  } catch (error) {
    console.log(`1. events/list with extensions capability: FAILED (${error.message})`);
  }
  await client.close();
  server.close();
}

// 2 and 3. Also advertise the legacy top-level `events` key so the requests get through.
const store = memoryStore();
const { server, received, url } = await startServer({
  events: {},
  extensions: { [EVENTS]: {} },
});
const client = await createMCPClient({
  transport: { type: 'http', url },
  experimental_events: { store },
});
await client.experimental_events.subscribe({
  name: 'incident.created',
  delivery: { mode: 'webhook', url: 'https://receiver.example/hooks' },
});
const [subscription] = store.records.values();
await client.experimental_events.unsubscribe({ key: subscription.key });
for (const { method, mcpName } of received.filter(r => /^events\/(un)?subscribe$/.test(r.method))) {
  console.log(`2. ${method}: Mcp-Name header = ${JSON.stringify(mcpName)}`);
}
await client.close();
server.close();

// 3. A signed delivery whose webhook-id is a per-message ID, not the eventId.
await store.set({ ...subscription, id: 'sub_a3f1c8e2b0d49f7e', status: 'active' });
const webhook = createMCPEventWebhook({ store, onEvent: async () => {} });
const secret = Buffer.from(subscription.delivery.secret.slice('whsec_'.length), 'base64');

async function deliver(webhookId) {
  const body = JSON.stringify({
    eventId: 'evt_1',
    name: 'incident.created',
    timestamp: new Date().toISOString(),
    data: {},
    cursor: null,
  });
  const timestamp = String(Math.floor(Date.now() / 1000));
  const signature = createHmac('sha256', secret)
    .update(`${webhookId}.${timestamp}.${body}`)
    .digest('base64');
  const response = await webhook(
    new Request(subscription.delivery.url, {
      method: 'POST',
      headers: {
        'content-type': 'application/json',
        'webhook-id': webhookId,
        'webhook-timestamp': timestamp,
        'webhook-signature': `v1,${signature}`,
        'X-MCP-Subscription-Id': 'sub_a3f1c8e2b0d49f7e',
      },
      body,
    }),
  );
  return response.status;
}

const perMessageId = `msg_${randomBytes(12).toString('base64url')}`;
console.log(`3. webhook-id ${perMessageId} (per message, as SEP-3415 requires): HTTP ${await deliver(perMessageId)}`);
console.log(`3. webhook-id evt_1 (equal to eventId): HTTP ${await deliver('evt_1')}`);
```

